mapper.select:
SELECT 
  FROM sys15_corp
 WHERE sys15_company_id = #{companyId}
   AND COALESCE(sys15_corp_type,'9') LIKE #{corpType}
   AND CONCAT(sys15_corp_nm, sys15_corp_cd) ILIKE #{searchText}

   AND COALESCE(sys15_use_yn,'false') = 'true'

 ORDER BY sys15_corp_type, COALESCE(sys15_seq, 999999999), sys15_corp_nm collate "ko-KR-x-icu" asc

SELECT 
  FROM sys15_corp
 WHERE sys15_company_id = #{companyId}
   AND COALESCE(sys15_use_yn,'false') = 'true'
   AND COALESCE(sys15_corp_type,'9') LIKE #{corpType}
   AND CONCAT(sys15_corp_nm, sys15_corp_cd, sys15_note) ILIKE #{searchText}
 ORDER BY sys15_corp_type, COALESCE(sys15_seq, 999999999), sys15_corp_nm collate "ko_KR.utf8" asc

SELECT COUNT(*)
  FROM sys15_corp
 WHERE sys15_company_id = #{companyId}
   AND sys15_corp_cd = #{corpCode}
   AND sys15_corp_id != #{corpId}
   AND sys15_use_yn = 'true'

SELECT #{bizNo}||
       lpad(cast(coalesce(max(case when length(substr(sys15_corp_cd,11)) = 0 then 0
                                   else cast(trim(substr(sys15_corp_cd,11)) as numeric) end),0) + 1 as varchar), 2, '00')
  FROM sys15_corp
 WHERE sys15_company_id = #{companyId}
   AND replace(sys15_biz_no,'-','') = #{bizNo}

mapper.delete:
DELETE FROM sys15_corp
 WHERE sys15_company_id = #{companyId}
   AND sys15_corp_id IN
#{corpId}
